[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Chocolate Retail Sales Performance Report 2023–2024</title>
  <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
  <style>
    :root {
      --brand-deep:    #2C1A0E;
      --brand-dark:    #4A2511;
      --brand-mid:     #7B3F1E;
      --brand-accent:  #C8762A;
      --brand-gold:    #D4A843;
      --brand-cream:   #F5E6D3;
      --brand-light:   #FDF8F4;
      --text-primary:  #1A1108;
      --text-secondary:#5C4A35;
      --text-muted:    #9A8573;
      --border:        #E8D5C0;
      --white:         #FFFFFF;
      --green:         #2E7D32;
      --red:           #C62828;
    }

    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
      background: var(--brand-light);
      color: var(--text-primary);
      line-height: 1.6;
      font-size: 15px;
    }

    /* ── Cover ── */
    .cover {
      background: linear-gradient(135deg, var(--brand-deep) 0%, var(--brand-dark) 50%, var(--brand-mid) 100%);
      color: var(--white);
      padding: 80px 60px 64px;
      position: relative;
      overflow: hidden;
    }
    .cover::before {
      content: '';
      position: absolute;
      top: -80px; right: -80px;
      width: 420px; height: 420px;
      border-radius: 50%;
      background: rgba(212,168,67,.12);
    }
    .cover::after {
      content: '';
      position: absolute;
      bottom: -60px; left: -60px;
      width: 280px; height: 280px;
      border-radius: 50%;
      background: rgba(212,168,67,.08);
    }
    .cover-inner { position: relative; z-index: 1; max-width: 860px; }
    .cover-badge {
      display: inline-block;
      background: rgba(212,168,67,.25);
      border: 1px solid rgba(212,168,67,.5);
      color: var(--brand-gold);
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 2px;
      text-transform: uppercase;
      padding: 5px 14px;
      border-radius: 20px;
      margin-bottom: 24px;
    }
    .cover h1 {
      font-size: 42px;
      font-weight: 800;
      line-height: 1.15;
      margin-bottom: 16px;
      letter-spacing: -0.5px;
    }
    .cover-sub {
      font-size: 17px;
      color: rgba(255,255,255,.75);
      max-width: 580px;
      margin-bottom: 48px;
    }
    .cover-meta {
      display: flex;
      gap: 40px;
      border-top: 1px solid rgba(255,255,255,.15);
      padding-top: 28px;
      flex-wrap: wrap;
    }
    .cover-meta-item label {
      display: block;
      font-size: 10px;
      font-weight: 700;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      color: rgba(255,255,255,.5);
      margin-bottom: 4px;
    }
    .cover-meta-item span {
      font-size: 14px;
      color: rgba(255,255,255,.9);
      font-weight: 500;
    }

    /* ── Layout ── */
    .container {
      max-width: 1080px;
      margin: 0 auto;
      padding: 0 40px;
    }

    /* ── Sections ── */
    .section {
      padding: 56px 0;
      border-bottom: 1px solid var(--border);
    }
    .section:last-child { border-bottom: none; }

    .section-header {
      display: flex;
      align-items: flex-start;
      gap: 20px;
      margin-bottom: 36px;
    }
    .section-number {
      flex-shrink: 0;
      width: 36px; height: 36px;
      background: var(--brand-accent);
      color: var(--white);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 13px;
      font-weight: 800;
      margin-top: 3px;
    }
    .section-title-wrap h2 {
      font-size: 26px;
      font-weight: 800;
      color: var(--brand-deep);
      letter-spacing: -0.3px;
      margin-bottom: 4px;
    }
    .section-title-wrap p {
      color: var(--text-secondary);
      font-size: 14px;
    }

    /* ── KPI Cards ── */
    .kpi-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
      margin-bottom: 40px;
    }
    .kpi-card {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 28px 24px 22px;
      position: relative;
      overflow: hidden;
      transition: box-shadow .2s;
    }
    .kpi-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0;
      height: 4px;
      background: var(--brand-accent);
    }
    .kpi-card.primary::before { background: var(--brand-deep); }
    .kpi-card.secondary::before { background: var(--brand-gold); }
    .kpi-card .kpi-label {
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-bottom: 10px;
    }
    .kpi-card .kpi-value {
      font-size: 34px;
      font-weight: 800;
      color: var(--brand-deep);
      letter-spacing: -1px;
      line-height: 1.1;
      margin-bottom: 8px;
    }
    .kpi-card .kpi-sub {
      font-size: 12px;
      color: var(--text-muted);
    }
    .kpi-card .kpi-badge {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      font-size: 12px;
      font-weight: 700;
      padding: 3px 9px;
      border-radius: 12px;
      margin-top: 6px;
    }
    .kpi-badge.up   { background: #E8F5E9; color: var(--green); }
    .kpi-badge.down { background: #FFEBEE; color: var(--red); }

    /* ── Summary Narrative ── */
    .summary-narrative {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 28px 32px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 32px;
    }
    .narrative-block h4 {
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--brand-accent);
      margin-bottom: 10px;
    }
    .narrative-block p {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.7;
    }

    /* ── Chart Containers ── */
    .chart-card {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 28px 28px 20px;
      margin-bottom: 24px;
    }
    .chart-card h3 {
      font-size: 16px;
      font-weight: 700;
      color: var(--brand-deep);
      margin-bottom: 6px;
    }
    .chart-card .chart-subtitle {
      font-size: 13px;
      color: var(--text-muted);
      margin-bottom: 24px;
    }
    .chart-wrapper { position: relative; }

    .chart-row { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }

    /* ── Data Tables ── */
    .data-table-wrap {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: 14px;
      overflow: hidden;
      margin-bottom: 24px;
    }
    .data-table-wrap h3 {
      font-size: 15px;
      font-weight: 700;
      color: var(--brand-deep);
      padding: 20px 24px 0;
      margin-bottom: 16px;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13.5px;
    }
    thead th {
      background: var(--brand-cream);
      color: var(--text-secondary);
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 1px;
      text-transform: uppercase;
      padding: 11px 16px;
      text-align: left;
      border-bottom: 1px solid var(--border);
    }
    tbody td {
      padding: 11px 16px;
      border-bottom: 1px solid #F0E8DE;
      color: var(--text-primary);
    }
    tbody tr:last-child td { border-bottom: none; }
    tbody tr:hover { background: #FDF5EE; }
    .rank-badge {
      display: inline-flex;
      width: 24px; height: 24px;
      border-radius: 6px;
      align-items: center;
      justify-content: center;
      font-size: 11px;
      font-weight: 800;
      background: var(--brand-cream);
      color: var(--brand-mid);
    }
    .rank-badge.gold   { background: #FFF9E0; color: #B8860B; }
    .rank-badge.silver { background: #F5F5F5; color: #757575; }
    .rank-badge.bronze { background: #FBE9E7; color: #BF360C; }

    /* ── Insight Boxes ── */
    .insight-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 24px; }
    .insight-box {
      background: var(--brand-cream);
      border: 1px solid var(--border);
      border-radius: 12px;
      padding: 22px 20px;
    }
    .insight-box .insight-icon { font-size: 22px; margin-bottom: 10px; }
    .insight-box h4 { font-size: 13px; font-weight: 700; color: var(--brand-deep); margin-bottom: 6px; }
    .insight-box p { font-size: 13px; color: var(--text-secondary); line-height: 1.6; }

    /* ── YoY Comparison ── */
    .yoy-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-bottom: 32px; }
    .yoy-card {
      background: var(--white);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 22px 20px;
      text-align: center;
    }
    .yoy-card .yoy-label { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--text-muted); margin-bottom: 12px; }
    .yoy-year { font-size: 13px; font-weight: 600; color: var(--text-secondary); margin-bottom: 2px; }
    .yoy-val { font-size: 24px; font-weight: 800; color: var(--brand-deep); }
    .yoy-divider { width: 1px; background: var(--border); margin: 8px auto; height: 16px; }
    .yoy-change { font-size: 14px; font-weight: 700; color: var(--green); margin-top: 10px; }

    /* ── Discount Impact ── */
    .discount-grid { display: grid; grid-template-columns: 5fr 4fr; gap: 24px; }
    .discount-stat-row {
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 14px 20px;
      border-bottom: 1px solid #F0E8DE;
    }
    .discount-stat-row:last-child { border-bottom: none; }
    .discount-label { flex: 0 0 160px; font-weight: 600; font-size: 14px; color: var(--brand-deep); }
    .discount-bar-wrap { flex: 1; }
    .discount-bar {
      height: 8px;
      border-radius: 4px;
      background: var(--brand-cream);
      overflow: hidden;
      margin-bottom: 4px;
    }
    .discount-bar-fill { height: 100%; border-radius: 4px; background: var(--brand-accent); }
    .discount-bar-fill.dim { background: var(--brand-gold); opacity: 0.65; }
    .discount-bar-fill.dimmer { background: var(--brand-gold); opacity: 0.4; }
    .discount-bar-label { font-size: 11px; color: var(--text-muted); }
    .discount-val { flex: 0 0 80px; text-align: right; font-size: 15px; font-weight: 700; color: var(--brand-deep); }

    /* ── Footer ── */
    footer {
      background: var(--brand-deep);
      color: rgba(255,255,255,.6);
      text-align: center;
      padding: 32px 40px;
      font-size: 13px;
    }
    footer strong { color: rgba(255,255,255,.9); }

    /* ── Divider ── */
    .section-divider { border: none; border-top: 2px solid var(--border); margin: 40px 0; }

    @media print {
      .section { page-break-inside: avoid; }
    }
  </style>
</head>
