<!-- ══════════════════ COVER ══════════════════ -->
<div class="cover">
  <div class="container">
    <div class="cover-inner">
      <div class="cover-badge">Management Report &nbsp;·&nbsp; Confidential</div>
      <h1>Chocolate Retail Sales<br/>Performance Report</h1>
      <p class="cover-sub">
        A comprehensive analysis of 50,000 retail transactions across stores, products,
        and customer segments — covering fiscal years 2023 and 2024.
      </p>
      <div class="cover-meta">
        <div class="cover-meta-item">
          <label>Reporting Period</label>
          <span>January 2023 – December 2024</span>
        </div>
        <div class="cover-meta-item">
          <label>Transactions Analyzed</label>
          <span>50,000 orders</span>
        </div>
        <div class="cover-meta-item">
          <label>Prepared For</label>
          <span>Retail Management</span>
        </div>
        <div class="cover-meta-item">
          <label>Report Date</label>
          <span>April 2026</span>
        </div>
      </div>
    </div>
  </div>
</div>

<!-- ══════════════════ EXECUTIVE SUMMARY ══════════════════ -->
<div class="section" id="executive-summary">
  <div class="container">
    <div class="section-header">
      <div class="section-number">01</div>
      <div class="section-title-wrap">
        <h2>Executive Summary</h2>
        <p>Key performance indicators and headline findings across the two-year reporting period.</p>
      </div>
    </div>

    <!-- Primary KPI Row -->
    <div class="kpi-grid">
      <div class="kpi-card primary">
        <div class="kpi-label">Total Revenue</div>
        <div class="kpi-value">$1.275M</div>
        <div class="kpi-sub">$1,275,308.34 across all transactions</div>
        <div class="kpi-badge up">&#x2197; +1.72% YoY</div>
      </div>
      <div class="kpi-card primary">
        <div class="kpi-label">Total Profit</div>
        <div class="kpi-value">$510.5K</div>
        <div class="kpi-sub">$510,547.86 net profit (2023–2024)</div>
        <div class="kpi-badge up">&#x2197; +1.57% YoY</div>
      </div>
      <div class="kpi-card primary">
        <div class="kpi-label">Average Profit Margin</div>
        <div class="kpi-value">40.01%</div>
        <div class="kpi-sub">Remarkably consistent across all channels</div>
      </div>
      <div class="kpi-card secondary">
        <div class="kpi-label">Average Order Value</div>
        <div class="kpi-value">$25.51</div>
        <div class="kpi-sub">Per-transaction revenue average</div>
      </div>
      <div class="kpi-card secondary">
        <div class="kpi-label">Total Orders</div>
        <div class="kpi-value">50,000</div>
        <div class="kpi-sub">149,961 units sold in total</div>
        <div class="kpi-badge up">&#x2197; +1.45% YoY</div>
      </div>
      <div class="kpi-card secondary">
        <div class="kpi-label">Discount Utilization Rate</div>
        <div class="kpi-value">37.55%</div>
        <div class="kpi-sub">Of all orders applied a discount</div>
      </div>
    </div>

    <!-- Narrative -->
    <div class="summary-narrative">
      <div class="narrative-block">
        <h4>Headline Finding</h4>
        <p>
          The chocolate retail business delivered <strong>$1.275M in revenue</strong> and
          <strong>$510.5K in profit</strong> over the 2023–2024 period, maintaining an exceptional
          40% gross margin with striking consistency across all stores, products, and discount
          levels. Revenue grew modestly by 1.72% in 2024, driven by order volume growth rather
          than price increases.
        </p>
      </div>
      <div class="narrative-block">
        <h4>Strategic Highlights</h4>
        <p>
          Store performance is tightly clustered — the top-performing store (S075) outearns
          the #10 store by only ~4%. Similarly, top products are within 6% of each other
          by revenue. Discounts do not erode margins but do reduce absolute revenue per order
          by ~16%, suggesting promotional spend requires careful evaluation for volume uplift
          justification.
        </p>
      </div>
    </div>
  </div>
</div>

